head.script:
(() => {
  const root = document.documentElement;
  const shortViewportQuery = "(max-height: 499px)";
  const mobileLandscapeQuery = "(hover: none) and (pointer: coarse) and (orientation: landscape)";
  const memeDelayMs = 500;
  const releaseHoldMs = 500;
  let blackoutHoldUntil = 0;
  let blackoutTimer = 0;
  let memeTimer = 0;
  let wasBlackoutTarget = false;

  const isSecretRoute = () => location.pathname.startsWith("/secret");
  const isMainRoute = () => !isSecretRoute();
  const isBlackoutRoute = () => isMainRoute() || isSecretRoute();
  const matchesQuery = (query) =>
    typeof window.matchMedia === "function" && window.matchMedia(query).matches;
  const shouldBlackout = () =>
    isBlackoutRoute() && (matchesQuery(shortViewportQuery) || matchesQuery(mobileLandscapeQuery));
  const activeBlackoutClass = () =>
    isSecretRoute() ? "secret-viewport-blackout-active" : "main-viewport-blackout-active";
  const clearBlackoutClasses = () => {
    root.classList.remove("main-viewport-blackout-active", "secret-viewport-blackout-active");
  };
  const activeMemeClass = () =>
    isSecretRoute() ? "secret-viewport-blackout-meme-active" : "main-viewport-blackout-meme-active";
  const clearMemeClasses = () => {
    root.classList.remove("main-viewport-blackout-meme-active", "secret-viewport-blackout-meme-active");
  };
  const clearMemeTimer = () => {
    window.clearTimeout(memeTimer);
    memeTimer = 0;
  };
  const hideMeme = () => {
    clearMemeClasses();
  };
  const scheduleMeme = () => {
    clearMemeTimer();
    hideMeme();
    memeTimer = window.setTimeout(() => {
      memeTimer = 0;
      if (shouldBlackout()) {
        root.classList.add(activeMemeClass());
      }
    }, memeDelayMs);
  };
  const scheduleBlackoutRelease = () => {
    window.clearTimeout(blackoutTimer);
    const remainingHold = blackoutHoldUntil - Date.now();

    if (remainingHold > 0) {
      blackoutTimer = window.setTimeout(updateBlackout, remainingHold);
    } else {
      blackoutTimer = 0;
    }
  };
  const updateBlackout = ({ extendHoldOnClear = false } = {}) => {
    const targetIsActive = shouldBlackout();
    const holdIsActive = Date.now() < blackoutHoldUntil;

    if (targetIsActive) {
      window.clearTimeout(blackoutTimer);
      blackoutTimer = 0;
      clearBlackoutClasses();
      root.classList.add(activeBlackoutClass());

      if (!wasBlackoutTarget) {
        scheduleMeme();
      }
    } else {
      if (isSecretRoute()) {
        blackoutHoldUntil = 0;
      } else if (wasBlackoutTarget || holdIsActive || extendHoldOnClear) {
        blackoutHoldUntil = Date.now() + releaseHoldMs;
      }

      clearMemeTimer();
      hideMeme();

      const releaseIsActive = isBlackoutRoute() && Date.now() < blackoutHoldUntil;
      clearBlackoutClasses();
      if (releaseIsActive) {
        root.classList.add(activeBlackoutClass());
      }
      scheduleBlackoutRelease();
    }

    wasBlackoutTarget = targetIsActive;
  };
  const holdBlackout = () => {
    updateBlackout({ extendHoldOnClear: true });
    window.requestAnimationFrame(updateBlackout);
  };
  const watchMedia = (query) => {
    if (typeof window.matchMedia !== "function") return;

    const media = window.matchMedia(query);
    const onChange = () => updateBlackout();
    if (typeof media.addEventListener === "function") {
      media.addEventListener("change", onChange);
    } else if (typeof media.addListener === "function") {
      media.addListener(onChange);
    }
  };

  if ("scrollRestoration" in history) history.scrollRestoration = "manual";
  window.scrollTo(0, 0);
  root.classList.toggle("main-route-active", isMainRoute());
  updateBlackout();
  watchMedia(shortViewportQuery);
  watchMedia(mobileLandscapeQuery);
  window.addEventListener("orientationchange", holdBlackout, { passive: true });
  window.addEventListener("resize", updateBlackout, { passive: true });
  window.visualViewport?.addEventListener("resize", updateBlackout, { passive: true });
  window.screen?.orientation?.addEventListener("change", holdBlackout);
})();
